  ]
} }}

=export default async ({ page, context }) => {
  /*
   * CONFIGURACIÓN RÁPIDA
   * Cambia estos valores si quieres más o menos posts.
   *
   * MAX_POSTS_A_EXTRAER:
   * número máximo de posts candidatos que Browserless devuelve.
   *
   * SCROLL_PASADAS:
   * número de veces que baja por la página.
   * Más scrolls = más posts cargados, pero más lento.
   */
  const MAX_POSTS_A_EXTRAER = 30;
  const SCROLL_PASADAS = 20;
  const ESPERA_INICIAL_MS = 8000;
  const ESPERA_ENTRE_SCROLL_MS = 2500;

  /*
   * Tu versión de Browserless no soporta page.waitForTimeout().
   * Usamos sleep() para esperar.
   */
  const sleep = (ms) => new Promise(resolve => setTimeout(resolve, ms));

  await page.setViewport({ width: 1365, height: 2400 });

  /*
   * Aplicamos cookies de Facebook.
   * Van dentro de context.cookies, no como campo separado.
   */
  if (context.cookies && Array.isArray(context.cookies)) {
    await page.setCookie(...context.cookies);
  }

  await page.goto(context.url, {
    waitUntil: 'domcontentloaded',
    timeout: 120000,
  });

  await sleep(ESPERA_INICIAL_MS);

  for (let i = 0; i < SCROLL_PASADAS; i++) {
    await page.evaluate(() => window.scrollBy(0, window.innerHeight * 0.9));
    await sleep(ESPERA_ENTRE_SCROLL_MS);
  }

  /*
   * Intentamos abrir textos truncados:
   * See more / Ver más / Mostrar más
   */
  for (let i = 0; i < 5; i++) {
    await page.evaluate(() => {
      const labels = [
        'See more',
        'Ver más',
        'Mostrar más',
        'See translation',
        'Ver traducción',
      ];

      const nodes = [...document.querySelectorAll('div[role="button"], span, a')];

      for (const node of nodes) {
        const txt = String(node.innerText || node.textContent || '').trim();

        if (labels.includes(txt)) {
          try {
            node.click();
          } catch (e) {}
        }
      }
    });

    await sleep(1200);
  }

  const data = await page.evaluate((context, maxPosts) => {
    function cleanText(s) {
      return String(s || '')
        .replace(/\s+/g, ' ')
        .replace(/Ver original · Califica esta traducción/gi, '')
        .replace(/Ver original/gi, '')
        .replace(/Califica esta traducción/gi, '')
        .replace(/See translation/gi, '')
        .replace(/Rate this translation/gi, '')
        .trim();
    }

    function removeUiNoise(s) {
      return String(s || '')
        .replace(/\bLike\b/gi, '')
        .replace(/\bComment\b/gi, '')
        .replace(/\bShare\b/gi, '')
        .replace(/\bSend\b/gi, '')
        .replace(/\bFollow\b/gi, '')
        .replace(/\bAll reactions:\s*\d+/gi, '')
        .replace(/\bView more comments\b/gi, '')
        .replace(/\bWrite a comment\b/gi, '')
        .replace(/\s+/g, ' ')
        .trim();
    }

    function isBadText(t) {
      return /Forgot Account|Join Facebook|Log in|Create new account|Recover|Cookies|Meta ©|Privacy|Terms|Messenger|Watch|Marketplace|Gaming|Fundraisers/i.test(t);
    }

    function isProbablyCssGarbage(t) {
      return /x[a-z0-9]{5,}\s+x[a-z0-9]{5,}\s+x[a-z0-9]{5,}/i.test(t);
    }

    function isUsefulText(t) {
      if (!t) return false;
      if (t.length < 40) return false;
      if (isBadText(t)) return false;
      if (isProbablyCssGarbage(t)) return false;
      return true;
    }

    function bestImage(root) {
      const imgs = [...root.querySelectorAll('img')]
        .map(img => img.currentSrc || img.src || '')
        .filter(Boolean)
        .filter(src => /^https?:\/\//i.test(src))
        .filter(src => /scontent|fbcdn/i.test(src))
        .filter(src => !/hsts-pixel|emoji|static\.xx\.fbcdn\.net|safe_image|p64x64|s64x64|c0\.0\./i.test(src));

      imgs.sort((a, b) => {
        const getSize = (u) => {
          const m = u.match(/s(\d+)x(\d+)/i);
          if (!m) return 0;
          return Number(m[1]) * Number(m[2]);
        };

        return getSize(b) - getSize(a);
      });

      return imgs[0] || '';
    }

    function cleanFacebookPostUrl(url) {
      if (!url) return context.url;

      try {
        const u = new URL(url);
        u.searchParams.delete('__cft__[0]');
        u.searchParams.delete('__tn__');
        u.searchParams.delete('mibextid');
        u.searchParams.delete('ref');
        u.searchParams.delete('refid');
        u.searchParams.delete('locale');
        return u.toString();
      } catch {
        return url;
      }
    }

    function bestPostUrl(root) {
      const links = [...root.querySelectorAll('a')]
        .map(a => a.href || '')
        .filter(Boolean)
        .filter(href =>
          href.includes('/photo') ||
          href.includes('fbid=') ||
          href.includes('/posts/') ||
          href.includes('/reel/') ||
          href.includes('story.php') ||
          href.includes('permalink.php')
        );

      return cleanFacebookPostUrl(links[0] || context.url);
    }

    function extractBetterPostText(root) {
      const allTexts = [];

      const possibleTextNodes = [
        ...root.querySelectorAll('[dir="auto"]'),
        ...root.querySelectorAll('span'),
        ...root.querySelectorAll('div'),
      ];

      for (const node of possibleTextNodes) {
        const text = removeUiNoise(cleanText(node.innerText || node.textContent || ''));

        if (!text) continue;
        if (text.length < 15) continue;
        if (isBadText(text)) continue;
        if (isProbablyCssGarbage(text)) continue;

        allTexts.push(text);
      }

      const unique = [];
      const seen = new Set();

      for (const t of allTexts) {
        const key = t.toLowerCase();
        if (seen.has(key)) continue;

        seen.add(key);

        if (/^(like|comment|share|send|follow|\d+|·)$/i.test(t)) continue;

        unique.push(t);
      }

      const promptLike = unique.filter(t => {
        const l = t.toLowerCase();

        return (
          l.includes('prompt') ||
          l.includes('chatgpt') ||
          l.includes('upload your image') ||
          l.includes('sube tu imagen') ||
          l.includes('open chatgpt') ||
          l.includes('abrir chatgpt') ||
          l.includes('midjourney') ||
          l.includes('stable diffusion') ||
          l.includes('dall-e')
        );
      });

      if (promptLike.length) {
        return promptLike
          .sort((a, b) => b.length - a.length)
          .slice(0, 4)
          .join('\n\n')
          .trim();
      }

      return removeUiNoise(cleanText(root.innerText || '')).slice(0, 6000);
    }

    function scoreText(text, image) {
      const lower = text.toLowerCase();
      let score = 0;

      if (lower.includes('prompt')) score += 80;
      if (lower.includes('chatgpt')) score += 60;
      if (lower.includes('upload your image')) score += 50;
      if (lower.includes('sube tu imagen')) score += 50;
      if (lower.includes('open chatgpt')) score += 50;
      if (lower.includes('abrir chatgpt')) score += 50;
      if (lower.includes('midjourney')) score += 40;
      if (lower.includes('stable diffusion')) score += 40;
      if (lower.includes('dall-e')) score += 40;
      if (lower.includes('retrato')) score += 20;
      if (lower.includes('render')) score += 15;
      if (lower.includes('photoshop')) score += 15;
      if (lower.includes('tutorial')) score += 15;
      if (lower.includes('diseño')) score += 10;
      if (lower.includes('branding')) score += 10;
      if (image) score += 25;

      score += Math.min(text.length / 100, 30);

      if (isBadText(text)) score -= 100;
      if (isProbablyCssGarbage(text)) score -= 100;

      return score;
    }

    const candidates = [];

    const articleNodes = [
      ...document.querySelectorAll('[role="article"]'),
      ...document.querySelectorAll('div[data-pagelet*="FeedUnit"]'),
      ...document.querySelectorAll('div'),
    ];

    for (const node of articleNodes) {
      const text = extractBetterPostText(node);

      if (!isUsefulText(text)) continue;

      const image = bestImage(node);
      const postUrl = bestPostUrl(node);
      const score = scoreText(text, image);

      if (text.length > 8000) continue;

      candidates.push({
        texto_limpio: text.slice(0, 6000),
        imagen_url: image,
        post_url: postUrl,
        score,
      });
    }

    candidates.sort((a, b) => b.score - a.score);

    const bodyText = cleanText(document.body.innerText || '');

    return {
      nombre: context.nombre,
      url: context.pagina_url,
      palabras_clave: context.palabras_clave,
      scrape_url: context.url,
      page_title: document.title,
      debug_candidates_count: candidates.length,
      debug_body_text: bodyText.slice(0, 5000),
      posts: candidates.slice(0, maxPosts),
    };
  }, context, MAX_POSTS_A_EXTRAER);

  return {
    data,
    type: 'application/json',
  };
};

