const crypto = require('crypto');

/*
 * CONFIGURACIÓN RÁPIDA
 * Cambia este número si quieres crear PDFs para más o menos posts por ejecución.
 *
 * Ejemplos:
 *  - 5  = máximo 5 PDFs
 *  - 15 = recomendado
 *  - 30 = máximo 30 PDFs
 */
const MAX_POSTS_A_PROCESAR = 30;

/*
 * CONFIGURACIÓN DE FILTRO
 * true  = solo guarda posts relacionados con prompts/IA o con tus palabras clave.
 * false = guarda cualquier post visible con texto/imagen útil.
 */
const SOLO_POSTS_RELEVANTES = false;

function hash(value = '') {
  return crypto
    .createHash('sha256')
    .update(String(value))
    .digest('hex')
    .slice(0, 24);
}

function cleanUrl(url = '') {
  url = String(url || '').trim();

  try {
    const u = new URL(url);

    // Quitamos parámetros que Facebook cambia constantemente
    u.searchParams.delete('__cft__[0]');
    u.searchParams.delete('__tn__');
    u.searchParams.delete('mibextid');
    u.searchParams.delete('ref');
    u.searchParams.delete('refid');
    u.searchParams.delete('locale');

    return u.origin + u.pathname + (u.search ? u.search : '');
  } catch {
    return url.split('?')[0];
  }
}

function getStablePostId(url = '') {
  url = String(url || '');

  // Reels: /reel/967376516157967/
  let m = url.match(/\/reel\/(\d+)/i);
  if (m) return `reel_${m[1]}`;

  // Fotos: fbid=106748115604529
  m = url.match(/[?&]fbid=(\d+)/i);
  if (m) return `fbid_${m[1]}`;

  // Posts: /posts/123...
  m = url.match(/\/posts\/([^/?#]+)/i);
  if (m) return `post_${m[1]}`;

  // Stories: story_fbid=123
  m = url.match(/[?&]story_fbid=(\d+)/i);
  if (m) return `story_${m[1]}`;

  // Permalink: permalink.php?story_fbid=123&id=456
  m = url.match(/permalink\.php.*?[?&]story_fbid=(\d+)/i);
  if (m) return `story_${m[1]}`;

  // Fallback estable: URL limpia
  return cleanUrl(url);
}

function cleanFinalText(t = '') {
  return String(t || '')
    .replace(/\s+/g, ' ')
    .replace(/Forgot Account\?/gi, '')
    .replace(/Join Facebook/gi, '')
    .replace(/Log in/gi, '')
    .replace(/Create new account/gi, '')
    .replace(/Posts About Reels/gi, '')
    .replace(/\bLike\b/gi, '')
    .replace(/\bComment\b/gi, '')
    .replace(/\bShare\b/gi, '')
    .replace(/\bSend\b/gi, '')
    .replace(/\bSee more\b/gi, '')
    .replace(/\bVer más\b/gi, '')
    .replace(/\s+/g, ' ')
    .trim();
}

function isBadPostText(t = '') {
  if (!t || t.length < 40) return true;

  if (/Forgot Account|Join Facebook|Log in to continue|Create new account|Recover/i.test(t)) {
    return true;
  }

  // Clases CSS raras de Facebook
  if (/x[a-z0-9]{5,}\s+x[a-z0-9]{5,}\s+x[a-z0-9]{5,}/i.test(t)) {
    return true;
  }

  return false;
}

function scorePost(post) {
  const text = String(post.texto_limpio || '').toLowerCase();
  let score = Number(post.score || 0);

  if (text.includes('prompt')) score += 80;
  if (text.includes('chatgpt')) score += 60;
  if (text.includes('sube tu imagen')) score += 60;
  if (text.includes('upload your image')) score += 60;
  if (text.includes('abrir chatgpt')) score += 60;
  if (text.includes('open chatgpt')) score += 60;
  if (text.includes('midjourney')) score += 50;
  if (text.includes('stable diffusion')) score += 50;
  if (text.includes('dall-e')) score += 50;
  if (text.includes('retrato')) score += 30;
  if (text.includes('portrait')) score += 30;
  if (text.includes('render')) score += 25;
  if (text.includes('photoshop')) score += 20;
  if (text.includes('tutorial')) score += 20;
  if (text.includes('diseño')) score += 15;
  if (text.includes('branding')) score += 15;
  if (post.imagen_url) score += 25;

  return score;
}

function getFiltroContenido(data, j) {
  const raw =
    data.filtro_contenido ||
    j.filtro_contenido ||
    data.palabras_clave ||
    j.palabras_clave ||
    '';

  return String(raw)
    .split(',')
    .map(x => x.trim().toLowerCase())
    .filter(Boolean);
}

function hasPromptSignal(text = '') {
  const t = String(text || '').toLowerCase();

  return (
    t.includes('prompt') ||
    t.includes('chatgpt') ||
    t.includes('sube tu imagen') ||
    t.includes('upload your image') ||
    t.includes('abrir chatgpt') ||
    t.includes('open chatgpt') ||
    t.includes('midjourney') ||
    t.includes('stable diffusion') ||
    t.includes('dall-e') ||
    t.includes('retrato') ||
    t.includes('portrait') ||
    t.includes('render octane') ||
    t.includes('image prompt') ||
    t.includes('ai image') ||
    t.includes('generative ai')
  );
}

function matchesUserFilter(text = '', filtros = []) {
  if (!filtros.length) return true;

  const t = String(text || '').toLowerCase();

  return filtros.some(f => t.includes(f));
}

const out = [];

for (const item of items) {
  const j = item.json || {};

  const data =
    j.data ||
    j.body?.data ||
    j.response?.data ||
    j;

  let posts = Array.isArray(data.posts) ? data.posts : [];
  const filtros = getFiltroContenido(data, j);

  posts = posts
    .map(post => ({
      ...post,
      texto_limpio: cleanFinalText(post.texto_limpio || ''),
      post_url: cleanUrl(post.post_url || data.url || j.url || ''),
    }))

    // Quita login, CSS y basura
    .filter(post => !isBadPostText(post.texto_limpio))

    // Debe tener imagen real o texto suficiente
    .filter(post => post.imagen_url || post.texto_limpio.length > 120)

    // Filtro de relevancia
    .filter(post => {
      if (!SOLO_POSTS_RELEVANTES) return true;

      const texto = post.texto_limpio || '';
      const coincideFiltro = matchesUserFilter(texto, filtros);
      const tienePrompt = hasPromptSignal(texto);

      if (tienePrompt) return true;
      if (post.imagen_url && coincideFiltro) return true;

      return false;
    })

    .sort((a, b) => scorePost(b) - scorePost(a));

  if (!posts.length) {
    out.push({
      json: {
        ...j,
        nombre: data.nombre || j.nombre || 'Facebook',
        cuenta: data.nombre || j.nombre || 'Facebook',
        url: data.url || j.url || '',
        pagina_url: data.url || j.url || '',
        scrape_ok: false,
        post_nuevo: false,
        es_nuevo: false,
        estado: 'SIN_POSTS_UTILES',
        motivo: 'No se encontraron posts que coincidan con prompts/IA o filtros de contenido',
        debug_candidates_count: data.debug_candidates_count || 0,
        debug_body_text: data.debug_body_text || data.page_text_sample || '',
      },
    });
    continue;
  }

  const unique = new Map();

  /*
   * AQUÍ SE LIMITA CUÁNTOS POSTS SE CONVIERTEN EN ITEMS
   * Cada item que salga de aquí podrá generar 1 PDF.
   * Cambia MAX_POSTS_A_PROCESAR arriba del todo.
   */
  for (const post of posts.slice(0, MAX_POSTS_A_PROCESAR)) {
    const texto = String(post.texto_limpio || '').trim();
    const imagen = String(post.imagen_url || '').trim();
    const postUrl = cleanUrl(post.post_url || data.url || j.url || '');

    /*
     * IMPORTANTE:
     * Sacamos un ID estable del post/reel/foto.
     * Así no se repite aunque Facebook añada parámetros nuevos a la URL.
     */
    const postId = getStablePostId(postUrl);

    /*
     * IMPORTANTE:
     * El hash depende del ID estable, no del texto ni de likes/comentarios.
     * Así el mismo post no se vuelve a procesar si cambian reacciones o comentarios.
     */
    const postHash = hash(postId);

    if (!postId || !postHash) continue;

    if (unique.has(postHash)) continue;

    unique.set(postHash, {
      cuenta: data.nombre || j.nombre || 'Facebook',
      nombre: data.nombre || j.nombre || 'Facebook',

      // URL de la página/cuenta origen
      url: data.url || j.url || '',
      pagina_url: data.url || j.url || '',

      // Datos del post
      post_url: postUrl,
      post_hash: postHash,
      post_id: postId,

      fecha_detectado: new Date().toISOString().slice(0, 10),
      texto_limpio: texto,
      imagen_url: imagen,

      palabras_clave: data.palabras_clave || j.palabras_clave || '',
      categoria: data.palabras_clave || j.palabras_clave || '',

      scrape_ok: true,
      estado: 'OK',
      motivo: 'Post visible extraído desde DOM con sesión',

      debug_score: scorePost(post),
      debug_original_post_url: post.post_url || '',
      debug_stable_post_id: postId,
    });
  }

  for (const post of unique.values()) {
    out.push({ json: post });
  }
}

return out;

const j = $json;

const prompt_ia = `
Eres un analista de contenido para crear ideas de prompts de IA.

Analiza SOLO la información disponible. No inventes datos.

Cuenta: ${j.nombre || j.cuenta}
Post URL: ${j.post_url || j.url}
Página origen: ${j.cuenta_url || j.original_url || ''}
Palabras clave esperadas: ${j.palabras_clave}

Texto del post:
${j.texto_limpio}

Imagen detectada:
${j.imagen_url || 'No se detectó imagen'}

Devuelve la respuesta en Markdown con esta estructura:

# Análisis de ${j.nombre || j.cuenta}

## Resumen
Resume qué contiene este post.

## Texto / prompt detectado
Si el post incluye un prompt, extráelo completo. Si está en español, mantenlo en español.

## Estilo visual detectado
Describe la estética, composición, colores, sujeto, iluminación y detalles relevantes de la imagen si hay URL de imagen.

## Ideas de prompts
Crea 5 prompts útiles basados en el post.

## Recomendación
Di si merece la pena guardar este post en PDF: SÍ o NO, y por qué.
`.trim();

return { json: { ...j, prompt_ia } };

const ai = $json;
const base = $('Preparar prompt IA').item.json;

function getAiText(j) {
  if (typeof j === 'string') return j;
  return String(
    j.output?.text ||
    j.output ||
    j.text ||
    j.content ||
    j.message?.content ||
    j.message ||
    j.response?.content ||
    j.response ||
    j.result ||
    j.data ||
    ''
  );
}

const promptFinal = getAiText(ai).trim();

return {
  json: {
    fecha: base.fecha_detectado || base.ultima_revision,
    cuenta: base.nombre || base.cuenta,
    texto: base.texto_limpio,
    prompt: promptFinal,
    imagen_url: base.imagen_url || '',
    post_url: base.post_url || base.url,
    cuenta_url: base.cuenta_url || base.original_url || '',
    categoria: base.palabras_clave,
    exportado_pdf: 'NO',
    post_hash: base.post_hash,
    ultimo_hash: base.ultimo_hash || base.post_hash,
    url: base.post_url || base.url,
    update_url: base.cuenta_url || base.original_url || base.url,
    ultima_revision: base.ultima_revision,
  },
};

let base = {};
try { base = $('Renombrar PDF').item.json; } catch (e) {}
if (!base.update_url) { try { base = $('Preparar fila Resultado').item.json; } catch (e) {} }
if (!base.update_url) { try { base = $('Preparar prompt IA').item.json; } catch (e) {} }

return {
  json: {
    url: base.update_url || base.cuenta_url || base.original_url || base.url,
    nombre: base.cuenta || base.nombre,
    ultima_revision: base.ultima_revision || base.fecha,
    ultimo_hash: base.post_hash || base.ultimo_hash,
    estado: 'OK',
    motivo: 'Post nuevo procesado',
  },
};

const j = $json;

let estado = j.scrape_ok && !j.post_nuevo ? 'SIN_POSTS_NUEVOS' : (j.scrape_status || j.estado || 'SIN_TEXTO_UTIL');
let motivo = j.scrape_ok && !j.post_nuevo ? 'Post ya registrado en hoja Posts' : (j.scrape_motivo || j.motivo || 'No se obtuvo contenido útil');

return {
  json: {
    url: j.cuenta_url || j.original_url || j.url,
    nombre: j.nombre || j.cuenta,
    ultima_revision: j.ultima_revision,
    ultimo_hash: j.post_hash || '',
    estado,
    motivo,
  },
};

