const items = $input.all();
const htmlItems = $('Preparar HTML PDF').all();

return items.map((item, index) => {
  const meta = htmlItems[index]?.json || {};
  const filename = meta.pdf_filename || `documento_${Date.now()}.pdf`;

  item.json = {
    ...meta,
    ...item.json,
    pdf_filename: filename,
  };

  if (item.binary?.data) {
    item.binary.data.fileName = filename;
    item.binary.data.mimeType = 'application/pdf';
    item.binary.data.fileExtension = 'pdf';
  }

