function esc(v) {
  return String(v ?? '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;');
}

function formatPostText(raw = '') {
  let t = String(raw || '').trim();

  // Limpieza básica de ruido de Facebook
  t = t
    .replace(/\bLike\b/gi, '')
    .replace(/\bComment\b/gi, '')
    .replace(/\bShare\b/gi, '')
    .replace(/\bSend\b/gi, '')
    .replace(/\bSee more\b/gi, '')
    .replace(/\bVer más\b/gi, '')
    .replace(/\bMostrar más\b/gi, '')
    .replace(/\s+/g, ' ')
    .trim();

  // Saltos antes de pasos tipo "1. Open ChatGPT 2. Upload..."
  t = t.replace(/\s+(\d+\.)\s+/g, '\n$1 ');

  // Saltos antes de palabras clave
  t = t
    .replace(/\s+(Prompt\s*:?\s*)/gi, '\n\n$1')
    .replace(/\s+(Negative prompt\s*:?\s*)/gi, '\n\n$1')
    .replace(/\s+(Steps\s*:?\s*)/gi, '\n\n$1')
    .replace(/\s+(Settings\s*:?\s*)/gi, '\n\n$1')
    .replace(/\s+(Seed\s*:?\s*)/gi, '\n\n$1')
    .replace(/\s+(Model\s*:?\s*)/gi, '\n\n$1');

  // Si hay comillas largas, intenta separarlas
  t = t.replace(/["“]\s*([^"”]{120,})\s*["”]/g, '\n\n"$1"\n');

  // Evitar demasiados saltos
  t = t.replace(/\n{3,}/g, '\n\n').trim();

  const lines = t.split('\n').map(x => x.trim()).filter(Boolean);

  let html = '';
  let inPromptBlock = false;

  for (const line of lines) {
    const isStep = /^\d+\./.test(line);
    const isPromptTitle = /^prompt\s*:?\s*$/i.test(line) || /^prompt\s*:/i.test(line);
    const isNegativeTitle = /^negative prompt\s*:/i.test(line);
    const isQuotedLong = /^["“].{80,}/.test(line);

    if (isStep) {
      if (inPromptBlock) {
        html += `</div>`;
        inPromptBlock = false;
      }

      html += `<div class="step">${esc(line)}</div>`;
      continue;
    }

    if (isPromptTitle || isNegativeTitle) {
      if (inPromptBlock) {
        html += `</div>`;
      }

      const parts = line.split(/:\s*/);
      const title = parts[0] || 'Prompt';
      const rest = parts.slice(1).join(': ');

      html += `<div class="promptTitle">${esc(title)}</div>`;
      html += `<div class="promptBlock">`;
      inPromptBlock = true;

      if (rest) {
        html += `<p>${esc(rest)}</p>`;
      }

      continue;
    }

    if (isQuotedLong) {
      if (!inPromptBlock) {
        html += `<div class="promptBlock">`;
        inPromptBlock = true;
      }

      html += `<p>${esc(line)}</p>`;
      continue;
    }

    if (inPromptBlock) {
      html += `<p>${esc(line)}</p>`;
    } else {
      html += `<p>${esc(line)}</p>`;
    }
  }

  if (inPromptBlock) {
    html += `</div>`;
  }

  return html || '<p>No se pudo extraer texto del post.</p>';
}

