function normalizeFacebookUrl(url) {
  let u = String(url || '').trim();
  if (!u) return '';

  u = u.replace(/\/$/, '');

  if (/facebook\.com/i.test(u)) {
    try {
      const parsed = new URL(u);
      let path = parsed.pathname || '/';
      path = path.replace(/^\/+/, '').replace(/\/+$/, '');

      const isPost =
        /story\.php|posts|photos|videos|reel|permalink|photo\.php/i.test(path) ||
        parsed.searchParams.has('fbid');

      // Para páginas generales usamos m.facebook.com con sesión/cookies
      if (!isPost) {
        return `https://m.facebook.com/${path}`;
      }

      return `https://m.facebook.com/${path}${parsed.search || ''}`;
    } catch (e) {
      return u.replace(
        /^https?:\/\/(www\.|m\.|mbasic\.)?facebook\.com/i,
        'https://m.facebook.com'
      );
    }
  }

  return u;
}

