const crypto = require('crypto');

/*
 * PREPARAR FILA POST
 *
 * Este nodo guarda en la pestaña Posts los datos necesarios
 * para no repetir el mismo post en futuras ejecuciones.
 *
 * IMPORTANTE:
 * Si post_hash o post_id vienen vacíos, los calculamos aquí
 * usando la URL del post.
 */

const meta = $('Preparar HTML PDF').item.json;

function hash(value = '') {
  return crypto
    .createHash('sha256')
    .update(String(value))
    .digest('hex')
    .slice(0, 24);
}

function cleanUrl(url = '') {
  url = String(url || '').trim();

  try {
    const u = new URL(url);

    // Quitamos parámetros variables de Facebook
    u.searchParams.delete('__cft__[0]');
    u.searchParams.delete('__tn__');
    u.searchParams.delete('mibextid');
    u.searchParams.delete('ref');
    u.searchParams.delete('refid');
    u.searchParams.delete('locale');

    return u.origin + u.pathname + (u.search ? u.search : '');
  } catch {
    return url.split('?')[0];
  }
}

function getStablePostId(url = '') {
  url = String(url || '');

  // Reels: /reel/967376516157967/
  let m = url.match(/\/reel\/(\d+)/i);
  if (m) return `reel_${m[1]}`;

  // Fotos: fbid=106748115604529
  m = url.match(/[?&]fbid=(\d+)/i);
  if (m) return `fbid_${m[1]}`;

  // Posts numéricos: /posts/123456789
  m = url.match(/\/posts\/(\d+)/i);
  if (m) return `post_${m[1]}`;

  // Posts pfbid: /posts/pfbid0Y...
  m = url.match(/\/posts\/([^/?#]+)/i);
  if (m) return `post_${m[1]}`;

  // Stories
  m = url.match(/[?&]story_fbid=(\d+)/i);
  if (m) return `story_${m[1]}`;

  // Fallback estable
  return cleanUrl(url);
}

